import{_ as a,o as r,c as t,ag as o}from"./chunks/framework.DCKC-kU_.js";const h=JSON.parse('{"title":"Form Proposal: Schedule","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/schedule.md","filePath":"proposals/schedule.md"}'),n={name:"proposals/schedule.md"};function s(i,e,d,l,c,u){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="form-proposal-schedule" tabindex="-1">Form Proposal: Schedule <a class="header-anchor" href="#form-proposal-schedule" aria-label="Permalink to &quot;Form Proposal: Schedule&quot;">​</a></h1><p>Status: active Proposal; intended first v1alpha2 release <code>0.1.0</code>. A local candidate package exists under <code>forms/candidates/v1alpha2/</code>, but no released FormRef or public release identity exists yet.</p><h2 id="need-and-boundary" tabindex="-1">Need and boundary <a class="header-anchor" href="#need-and-boundary" aria-label="Permalink to &quot;Need and boundary&quot;">​</a></h2><p>Takosumi Cloud invokes one connected Resource on a recurring schedule. The candidate Form describes expression, timezone, and the exact target connection. Scheduler implementation, enable/disable policy, delivery transport, retry policy, credentials, capacity, and price remain host-owned.</p><h2 id="substrate-neutrality-review" tabindex="-1">Substrate-neutrality review <a class="header-anchor" href="#substrate-neutrality-review" aria-label="Permalink to &quot;Substrate-neutrality review&quot;">​</a></h2><p>A five-field cron expression, timezone, and one declared invocation connection can be implemented by an OS scheduler, Kubernetes CronJob, managed event scheduler, or edge trigger. Retry, catch-up, overlap, enablement, jitter, and delivery transport are excluded until they have independently testable shared semantics rather than provider defaults.</p><h2 id="lifecycle-and-security-risks" tabindex="-1">Lifecycle and security risks <a class="header-anchor" href="#lifecycle-and-security-risks" aria-label="Permalink to &quot;Lifecycle and security risks&quot;">​</a></h2><p>Expression changes should update in place when the host can preserve identity. Delete stops future delivery while retaining bounded audit. Import requires exact scheduler and target evidence. Invocation authority and secret payloads remain outside portable state.</p><h2 id="prior-art-and-gap" tabindex="-1">Prior art and gap <a class="header-anchor" href="#prior-art-and-gap" aria-label="Permalink to &quot;Prior art and gap&quot;">​</a></h2><p>OCCI Action/Link, TOSCA policies/triggers/workflows, Kubernetes CronJob, Crossplane managed schedulers, and Terraform scheduler/event-rule resources are applicable; CIMI has no focused recurring invocation resource. The gap is a small scheduler-to-Resource connection without provider event-target fields.</p>',10)])])}const m=a(n,[["render",s]]);export{h as __pageData,m as default};
